class SlidingWindowMemory:
    def __init__(self, max_messages: int = 6):
        self.max_messages = max_messages
        self.system_message = {'role': 'system', 'content': 'You are a helpful agent.'}
        self.history: list[dict] = []

    def add_message(self, role: str, content: str):
        self.history.append({'role': role, 'content': content})
        # Enforce sliding window (preserve last max_messages)
        if len(self.history) > self.max_messages:
            self.history = self.history[-self.max_messages:]

    def get_payload(self) -> list[dict]:
        return [self.system_message] + self.history

mem = SlidingWindowMemory(max_messages=4)
mem.add_message('user', 'Hello!')
mem.add_message('assistant', 'Hi! How can I help?')
mem.add_message('user', 'What is RAG?')
mem.add_message('assistant', 'RAG stands for Retrieval-Augmented Generation.')
mem.add_message('user', 'Give an example.')

print(f'Total messages in prompt: {len(mem.get_payload())}')
print(mem.get_payload())
